
-- Hackathon Digest: Supabase schema + all current data.
-- Paste into Supabase → SQL Editor → Run. Safe to run more than once (creates are idempotent,
-- inserts skip rows that already exist).
-- Generated 2026-11-19 from the site's database: Hack Club directory + reviewer-curated events
-- (including every hackathon already sent by the email digest).

begin;

-- ---------------------------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------------------------

-- One row per real-world hackathon, merged from all sources.
create table if not exists public.events (
  id                            uuid primary key default gen_random_uuid(),
  slug                          text not null unique,
  name                          text not null,
  organizer                     text,
  summary                       text,
  description                   text,
  website_url                   text,
  registration_url              text,
  rules_url                     text,
  start_at                      timestamptz,
  end_at                        timestamptz,
  timezone                      text,
  registration_deadline_at      timestamptz,
  registration_deadline_status  text not null default 'unverified' check (registration_deadline_status in ('verified','unverified')),
  submission_deadline_at        timestamptz,
  submission_deadline_status    text not null default 'unverified' check (submission_deadline_status in ('verified','unverified')),
  submission_deadline_source    text,
  format                        text not null check (format in ('online','in_person','hybrid')),
  venue                         text,
  city                          text,
  state                         text,
  country                       text,
  country_code                  text,
  region                        text,
  latitude                      double precision,
  longitude                     double precision,
  team_min                      integer,
  team_max                      integer,
  solo_allowed                  boolean,           -- null = not stated
  categories                    jsonb not null default '[]'::jsonb,
  technologies                  jsonb not null default '[]'::jsonb,
  perks                         jsonb not null default '[]'::jsonb,
  cost                          text check (cost in ('free','paid')),
  theme                         text,
  deliverables                  text,
  judging_criteria              text,
  prize_summary                 text,
  prizes                        jsonb,
  schedule                      jsonb,
  logo_url                      text,
  dedupe_key                    text not null,
  website_host                  text,
  hidden                        boolean not null default false,
  is_mock                       boolean not null default false,
  first_seen_at                 timestamptz not null default now(),
  last_verified_at              timestamptz,
  created_at                    timestamptz not null default now(),
  updated_at                    timestamptz not null default now()
);
create index if not exists events_dedupe_key   on public.events (dedupe_key);
create index if not exists events_website_host on public.events (website_host);
create index if not exists events_start_at     on public.events (start_at);

-- High-school eligibility, kept separate from event facts (own evidence and review cycle).
create table if not exists public.eligibility (
  event_id                      uuid primary key references public.events(id) on delete cascade,
  status                        text not null check (status in ('verified','unclear','ineligible')),
  high_school_allowed           boolean,
  education_levels              jsonb not null default '[]'::jsonb,
  min_age                       integer,
  max_age                       integer,
  grades                        jsonb not null default '[]'::jsonb,
  geographic_restrictions       text,
  international_allowed         boolean,
  requires_college_enrollment   boolean,
  method                        text not null,
  evidence                      jsonb not null default '[]'::jsonb,   -- [{url, quote, note}]
  source_url                    text,
  content_hash                  text,
  checked_at                    timestamptz not null default now(),
  notes                         text,
  manual                        boolean not null default false,
  needs_review                  boolean not null default false
);
create index if not exists eligibility_status on public.eligibility (status);

-- Every place an event was found; (source, external_id) is the stable identity for updates.
create table if not exists public.event_sources (
  id                            bigint generated by default as identity primary key,
  event_id                      uuid not null references public.events(id) on delete cascade,
  source                        text not null,
  external_id                   text not null,
  source_url                    text,
  normalized                    jsonb not null,
  raw                           jsonb,
  first_seen_at                 timestamptz not null default now(),
  last_seen_at                  timestamptz not null default now(),
  unique (source, external_id)
);
create index if not exists event_sources_event on public.event_sources (event_id);

-- Reviewer edits, applied on top of source data so re-ingestion never overwrites them.
create table if not exists public.event_overrides (
  event_id                      uuid not null references public.events(id) on delete cascade,
  field                         text not null,
  value                         jsonb not null,
  note                          text,
  updated_at                    timestamptz not null default now(),
  primary key (event_id, field)
);

create table if not exists public.ingestion_runs (
  id                            bigint generated by default as identity primary key,
  source                        text not null,
  started_at                    timestamptz not null default now(),
  finished_at                   timestamptz,
  status                        text not null check (status in ('running','succeeded','failed')),
  stats                         jsonb,
  error                         text
);

-- Organizer suggestions; never public until a reviewer approves them.
create table if not exists public.submissions (
  id                            bigint generated by default as identity primary key,
  created_at                    timestamptz not null default now(),
  status                        text not null default 'pending' check (status in ('pending','approved','rejected')),
  payload                       jsonb not null,
  contact_email                 text,
  review_note                   text,
  reviewed_at                   timestamptz,
  event_id                      uuid references public.events(id) on delete set null
);

-- ---------------------------------------------------------------------------------------------
-- What the public site reads: verified-eligible, not hidden, not closed.
-- "Closed" = verified submission deadline passed, or (no verified deadline) the event has ended.
-- Unconfirmed-deadline events are included with submission_deadline_status = 'unverified';
-- the site hides them by default.
-- ---------------------------------------------------------------------------------------------
create or replace view public.public_events
with (security_invoker = true) as
select e.id, e.slug, e.name, e.organizer, e.summary, e.description, e.website_url, e.registration_url, e.rules_url,
       e.start_at, e.end_at, e.timezone,
       e.registration_deadline_at, e.registration_deadline_status,
       e.submission_deadline_at, e.submission_deadline_status, e.submission_deadline_source,
       e.format, e.venue, e.city, e.state, e.country, e.country_code, e.region,
       e.team_min, e.team_max, e.solo_allowed, e.categories, e.technologies, e.perks, e.cost,
       e.theme, e.deliverables, e.judging_criteria, e.prize_summary, e.prizes, e.schedule, e.logo_url,
       e.first_seen_at, e.updated_at, e.last_verified_at,
       el.education_levels, el.min_age, el.max_age, el.grades, el.international_allowed,
       el.geographic_restrictions, el.method as eligibility_method, el.evidence as eligibility_evidence,
       el.checked_at as eligibility_checked_at, el.notes as eligibility_notes
from public.events e
join public.eligibility el on el.event_id = e.id
where el.status = 'verified'
  and not e.hidden
  and not e.is_mock
  and case
        when e.submission_deadline_status = 'verified' and e.submission_deadline_at is not null
          then e.submission_deadline_at > now()
        else coalesce(e.end_at, e.start_at) > now()
      end;

-- ---------------------------------------------------------------------------------------------
-- Row-level security. Visitors (anon key) can only read verified, visible listings and submit
-- suggestions. Everything else (ingestion, admin, reviews) uses the service-role key, which
-- bypasses RLS and must never be shipped to the browser.
-- ---------------------------------------------------------------------------------------------
alter table public.events          enable row level security;
alter table public.eligibility     enable row level security;
alter table public.event_sources   enable row level security;
alter table public.event_overrides enable row level security;
alter table public.ingestion_runs  enable row level security;
alter table public.submissions     enable row level security;

drop policy if exists "public reads verified events" on public.events;
create policy "public reads verified events" on public.events
  for select to anon, authenticated
  using (not hidden and not is_mock and exists (
    select 1 from public.eligibility el where el.event_id = events.id and el.status = 'verified'));

drop policy if exists "public reads verified eligibility" on public.eligibility;
create policy "public reads verified eligibility" on public.eligibility
  for select to anon, authenticated
  using (status = 'verified');

drop policy if exists "public reads sources of verified events" on public.event_sources;
create policy "public reads sources of verified events" on public.event_sources
  for select to anon, authenticated
  using (exists (select 1 from public.eligibility el where el.event_id = event_sources.event_id and el.status = 'verified'));

drop policy if exists "anyone can suggest an event" on public.submissions;
create policy "anyone can suggest an event" on public.submissions
  for insert to anon, authenticated
  with check (status = 'pending' and event_id is null and review_note is null and reviewed_at is null);

grant select on public.public_events to anon, authenticated;

-- ---------------------------------------------------------------------------------------------
-- Data
-- ---------------------------------------------------------------------------------------------
